.sl-contact-hub { background-color: var(--smartlearn-bg); color: var(--smartlearn-text); font-family: var(--smartlearn-body-font, system-ui, sans-serif); padding-block: clamp(2.5rem, 5vw, 4rem); padding-inline: clamp(1rem, 3vw, 2rem); }
.sl-contact-hub .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; }
.sl-contact-hub .header-banner { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 1rem); padding: clamp(1.25rem, 3vw, 2rem); display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-bottom: 2rem; }
.sl-contact-hub .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-weight: 800; font-size: clamp(1.5rem, 3vw, 2.25rem); color: var(--smartlearn-text); margin: 0 0 0.25rem; }
.sl-contact-hub .sl-subtitle { color: var(--smartlearn-text-muted); margin: 0; font-size: 0.95rem; }
.sl-contact-hub .sl-banner-emoji { font-size: 2.25rem; flex-shrink: 0; }
.sl-contact-hub .sl-cards-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.25rem; margin-bottom: 2rem; }
.sl-contact-hub .contact-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 1rem); padding: 1.5rem; text-align: center; display: flex; flex-direction: column; align-items: center; transition: transform 0.25s ease; }
.sl-contact-hub .contact-card:hover { transform: translateY(-4px); }
.sl-contact-hub .icon-wrap { width: 56px; height: 56px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 1rem; background-color: rgba(148, 163, 184, 0.12); background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent); color: var(--smartlearn-primary); }
.sl-contact-hub .sl-card-title { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.1rem; font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-contact-hub .sl-card-text { font-size: 0.925rem; color: var(--smartlearn-text-muted); margin: 0 0 1rem; }
.sl-contact-hub .sl-contact-link { color: var(--smartlearn-primary); text-decoration: none; font-weight: 600; }
.sl-contact-hub .sl-contact-link:hover { text-decoration: underline; }
.sl-contact-hub .sl-badge { margin-top: auto; display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.35rem 0.75rem; border-radius: 999px; font-size: 0.8rem; font-weight: 600; background-color: rgba(148, 163, 184, 0.12); background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, transparent); color: var(--smartlearn-text); }
.sl-contact-hub .sl-card-link { margin-top: auto; width: 100%; min-height: 40px; display: inline-flex; align-items: center; justify-content: center; padding: 0.5rem 0.75rem; border-radius: var(--smartlearn-radius, 0.5rem); background-color: var(--smartlearn-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.3)); color: var(--smartlearn-primary); font-size: 0.875rem; font-weight: 600; text-decoration: none; }
.sl-contact-hub .sl-card-link:hover { border-color: var(--smartlearn-primary); }
.sl-contact-hub .quick-form-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 1rem); padding: 1.5rem; margin-bottom: 1.5rem; }
.sl-contact-hub .sl-form-header { display: flex; align-items: center; gap: 1rem; margin-bottom: 1rem; }
.sl-contact-hub .form-icon { width: 44px; height: 44px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); }
.sl-contact-hub .sl-form-fields { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: center; }
.sl-contact-hub .sl-input { flex: 1 1 200px; min-height: 44px; padding: 0.625rem 1rem; border-radius: var(--smartlearn-radius, 0.5rem); background-color: var(--smartlearn-input-bg, var(--smartlearn-bg)); border: 1px solid var(--smartlearn-input-border, var(--smartlearn-card-border, rgba(148, 163, 184, 0.35))); color: var(--smartlearn-text); }
.sl-contact-hub .sl-input-grow { flex: 2 1 260px; }
.sl-contact-hub .sl-input:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 1px; }
.sl-contact-hub .sl-submit-btn { min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; padding: 0.625rem 1.5rem; border-radius: 999px; border: none; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-weight: 600; cursor: pointer; }
.sl-contact-hub .sl-submit-btn:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); }
.sl-contact-hub .sl-submit-btn:focus-visible, .sl-contact-hub a:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-contact-hub .sl-form-status { margin-top: 0.75rem; font-size: 0.9rem; font-weight: 600; color: var(--smartlearn-primary); min-height: 1.25em; }
.sl-contact-hub .sl-form-status.is-error { color: #dc2626; }
.sl-contact-hub .privacy-footer { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 0.75rem); padding: 1rem 1.5rem; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; }
.sl-contact-hub .sl-privacy-info { display: flex; align-items: center; gap: 0.875rem; color: var(--smartlearn-primary); }
.sl-contact-hub .sl-privacy-title { font-family: var(--smartlearn-heading-font, inherit); font-size: 1rem; font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.15rem; }
.sl-contact-hub .sl-privacy-link { color: var(--smartlearn-primary); font-weight: 600; text-decoration: none; white-space: nowrap; }
.sl-contact-hub .sl-privacy-link:hover { text-decoration: underline; }
[dir="rtl"] .sl-contact-hub .sl-arrow { display: inline-block; transform: scaleX(-1); }
@media (max-width: 991px) { .sl-contact-hub .sl-cards-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 575px) { .sl-contact-hub .sl-cards-grid { grid-template-columns: 1fr; } .sl-contact-hub .sl-banner-emoji { display: none; } .sl-contact-hub .sl-submit-btn { width: 100%; } }
@media (prefers-reduced-motion: reduce) { .sl-contact-hub .contact-card { transition: none; } .sl-contact-hub .contact-card:hover { transform: none; } }

