(function() {
  var init = function() {
    document.querySelectorAll('.sl-contact-hub').forEach(function(root, idx) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var uid = 'sl-chub-' + idx + '-' + Math.random().toString(36).slice(2, 7);
      var form = root.querySelector('.sl-form');
      if (!form) return;
      form.querySelectorAll('[data-sl-field]').forEach(function(input) {
        var key = input.getAttribute('data-sl-field');
        var fieldId = uid + '-' + key;
        input.id = fieldId;
        var label = form.querySelector('[data-sl-for="' + key + '"]');
        if (label) label.setAttribute('for', fieldId);
      });
      var status = form.querySelector('.sl-form-status');
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        var email = form.querySelector('[name="email"]');
        var msg = form.querySelector('[name="message"]');
        var emailVal = email ? email.value.trim() : '';
        var msgVal = msg ? msg.value.trim() : '';
        if (email) email.removeAttribute('aria-invalid');
        if (msg) msg.removeAttribute('aria-invalid');
        if (!emailVal || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailVal)) {
          if (email) { email.setAttribute('aria-invalid', 'true'); email.focus(); }
          if (status) { status.textContent = 'Please enter a valid email address.'; status.classList.add('is-error'); }
          return;
        }
        if (!msgVal) {
          if (msg) { msg.setAttribute('aria-invalid', 'true'); msg.focus(); }
          if (status) { status.textContent = 'Please enter a message before sending.'; status.classList.add('is-error'); }
          return;
        }
        if (status) { status.textContent = 'Thank you! Your message has been received.'; status.classList.remove('is-error'); }
        form.reset();
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
